CREATE COLUMN TABLE "TEST_AP"."OMIN" ("Entry" INTEGER CS_INT NOT NULL , "Number" INTEGER CS_INT, "Date" LONGDATE CS_LONGDATE, "BPCode" NVARCHAR(15), "BPName" NVARCHAR(100), "Currency" NVARCHAR(3), "LastBilled" DECIMAL(21,6) CS_FIXED, "Paid" DECIMAL(21,6) CS_FIXED, "CarryForw" DECIMAL(21,6) CS_FIXED, "CurAmount" DECIMAL(21,6) CS_FIXED, "BillAmount" DECIMAL(21,6) CS_FIXED, "OBPaid" DECIMAL(21,6) CS_FIXED, "OBLstJENum" INTEGER CS_INT, "Predeces" INTEGER CS_INT, "Successor" INTEGER CS_INT, "Series" INTEGER CS_INT, "Cancelled" NVARCHAR(1) DEFAULT 'N', "Address" NVARCHAR(254), PRIMARY KEY ("Entry")) UNLOAD PRIORITY 5  AUTO MERGE 